"""The question bank: every question Iceberg can ask, and which five appear on which day.

Each question is a dict. Fields:
  key      unique id (never reuse one: saved verdicts and statistics are filed under it)
  title    short name for lists ("Birds")           prompt   the question itself ("Name a bird")
  icon     an icon name from icons.js               hint     one line under the question
  rules    what players see under "How answers are judged"
Where the answers come from (any mix):
  roots    WordNet subtrees whose members are answers         inst   True to follow named instances (countries, gods)
  core     hand-written answers (always accepted)             aliases  {answer: [other names]}
  pattern  ("start" | "end" | "has", letters) for word questions
Shaping:
  top      how readily the most typical answers come to mind, 0 to 1 (drives the sample statistics)
  general  words too general to count      notin   common wrong answers      stop   words the dictionary files here by a minor sense
  collapse {synset: answer} everything under it counts as that answer      proper  True for names (keeps capitals)
  adj      True to accept the adjective for a noun answer (happy for happiness)

To add a day: write five new questions (new keys), add their keys as a row in DAYS, run tools/build_days.py.
"""


def t(text):
    """'eagle .5, owl .4' -> {'eagle': 0.5, 'owl': 0.4}"""
    out = {}
    for part in text.split(","):
        name, value = part.strip().rsplit(" ", 1)
        out[name.strip().lower()] = float(value)
    return out


def words(text):
    return [w.strip() for w in text.replace("\n", " ").split(",") if w.strip()]


ONE = "Different names for one thing count once."
Q = {}


def add(key, title, icon, prompt, hint, rules, **kw):
    assert key not in Q, key
    Q[key] = dict(key=key, title=title, icon=icon, prompt=prompt, hint=hint, rules=rules, **kw)


