# ---------------------------------------------------------------- word questions
def letters(key, kind, text):
    up = text.upper()
    prompt = {"start": f"Name a word that starts with {up}", "end": f"Name a word that ends in {up}", "has": f"Name a word with {up} in it"}[kind]
    title = {"start": f"{up} words", "end": f"-{up} words", "has": f"{up} words"}[kind]
    rule = {"start": f"Any real English word that starts with {up}.", "end": f"Any real English word that ends in {up}.", "has": f"Any real English word with {up} in it."}[kind]
    add(key, title, "letters:" + up, prompt, "Any real English word.",
        [rule, "Forms of one word count once: the plural, and verb forms like -ed and -ing.", "Names of people, places and brands don't count."], pattern=(kind, text))


